class TestArithmetic(Base):
    def test_int_plus_int(self):
        self.assertVal("2 + 3", 5)

    def test_int_minus_int(self):
        self.assertVal("2 - 5", -3)

    def test_int_times_int(self):
        self.assertVal("4 * 3", 12)

    def test_int_plus_float(self):
        self.assertVal("2 + 3.0", 5.0)

    def test_float_minus_int(self):
        self.assertVal("7.5 - 2", 5.5)

    def test_float_times_int(self):
        self.assertVal("2.0 * 3", 6.0)

    def test_division_is_float(self):
        self.assertVal("4 / 2", 2.0)

    def test_true_division(self):
        self.assertVal("7 / 2", 3.5)

    def test_division_by_zero(self):
        self.assertIsNone(self.val("1 / 0"))
        self.assertIsNone(self.val("0 / 0"))
        self.assertIsNone(self.val("1.5 / 0"))
        self.assertIsNone(self.val("1 / 0.0"))

    def test_division_by_zero_column(self):
        self.assertRowsExact(
            self.rows("SELECT price / 0 FROM products"),
            [(None,), (None,), (None,)],
        )

    def test_unary_minus_types(self):
        self.assertVal("-3", -3)
        self.assertVal("-2.5", -2.5)

    def test_column_arithmetic_types(self):
        self.assertRowsExact(
            self.rows("SELECT price * 2 FROM products"), [(50,), (25.0,), (14,)]
        )

    def test_string_plus_int_error(self):
        self.assertError("SELECT 'a' + 1 FROM one")

    def test_int_minus_string_error(self):
        self.assertError("SELECT 1 - 'a' FROM one")

    def test_string_times_int_error(self):
        self.assertError("SELECT 'a' * 2 FROM one")

    def test_string_division_error(self):
        self.assertError("SELECT 'a' / 2 FROM one")

    def test_string_from_column_arithmetic_error(self):
        self.assertError("SELECT name + 1 FROM products")

    def test_bool_arithmetic_error(self):
        self.assertError("SELECT TRUE + 1 FROM one")
        self.assertError("SELECT 2 * FALSE FROM one")
        self.assertError("SELECT TRUE - FALSE FROM one")
        self.assertError("SELECT TRUE / 1 FROM one")

    def test_unary_minus_string_error(self):
        self.assertError("SELECT -'a' FROM one")

    def test_unary_minus_bool_error(self):
        self.assertError("SELECT -TRUE FROM one")


class TestConcat(Base):
    def test_strings(self):
        self.assertVal("'a' || 'b'", "ab")

    def test_string_and_int(self):
        self.assertVal("'a' || 1", "a1")

    def test_int_and_int(self):
        self.assertVal("1 || 2", "12")

    def test_float(self):
        self.assertVal("'x' || 2.5", "x2.5")
        self.assertVal("'' || 1.0", "1.0")

    def test_chained(self):
        self.assertVal("'a' || 'b' || 'c'", "abc")

    def test_columns(self):
        self.assertRowsExact(
            self.rows("SELECT name || ':' || price FROM products"),
            [("widget:25",), ("gadget:12.5",), ("doohickey:7",)],
        )


# --------------------------------------------------------------------------
# Comparisons
# --------------------------------------------------------------------------


class TestComparisons(Base):
    def test_equal(self):
        self.assertIs(self.val("1 = 1"), True)
        self.assertIs(self.val("1 = 2"), False)

    def test_not_equal_both_spellings(self):
        self.assertIs(self.val("1 != 2"), True)
        self.assertIs(self.val("1 != 1"), False)
        self.assertIs(self.val("1 <> 2"), True)
        self.assertIs(self.val("1 <> 1"), False)

    def test_ordering_operators(self):
        self.assertIs(self.val("1 < 2"), True)
        self.assertIs(self.val("2 < 2"), False)
        self.assertIs(self.val("2 <= 2"), True)
        self.assertIs(self.val("3 <= 2"), False)
        self.assertIs(self.val("3 > 2"), True)
        self.assertIs(self.val("2 > 2"), False)
        self.assertIs(self.val("2 >= 2"), True)
        self.assertIs(self.val("1 >= 2"), False)

    def test_int_float_numeric(self):
        self.assertIs(self.val("2 = 2.0"), True)
        self.assertIs(self.val("1 < 1.5"), True)
        self.assertIs(self.val("10 > 9.99"), True)

    def test_strings_by_code_point(self):
        self.assertIs(self.val("'a' < 'b'"), True)
        self.assertIs(self.val("'B' < 'a'"), True)
        self.assertIs(self.val("'abc' < 'abd'"), True)
        self.assertIs(self.val("'ab' < 'abc'"), True)
        self.assertIs(self.val("'10' < '9'"), True)

    def test_string_equality_case_sensitive(self):
        self.assertIs(self.val("'a' = 'a'"), True)
        self.assertIs(self.val("'a' = 'A'"), False)

    def test_booleans(self):
        self.assertIs(self.val("TRUE = TRUE"), True)
        self.assertIs(self.val("TRUE = FALSE"), False)
        self.assertIs(self.val("TRUE != FALSE"), True)

    def test_number_vs_string_error(self):
        self.assertError("SELECT 1 = 'a' FROM one")
        self.assertError("SELECT 'a' < 1 FROM one")
        self.assertError("SELECT 1 = '1' FROM one")

    def test_column_number_vs_string_error(self):
        self.assertError("SELECT name FROM products WHERE name = 1")


class TestIn(Base):
