    def test_order_by_position_desc(self):
        self.assertEqual(
            self.names("SELECT name, price FROM products ORDER BY 1 DESC"),
            ["widget", "gadget", "doohickey"],
        )

    def test_order_by_expression(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY price * -1"),
            ["widget", "gadget", "doohickey"],
        )

    def test_order_by_expression_on_input_row(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY LENGTH(name), id DESC"),
            ["gadget", "widget", "doohickey"],
        )

    def test_nulls_first_ascending(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY bonus"),
            ["bob", "dave", "Eve", "Carol", "Alice"],
        )

    def test_nulls_last_descending(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY bonus DESC"),
            ["Alice", "Carol", "Eve", "bob", "dave"],
        )

    def test_stable_ascending(self):
        self.assertEqual(
