        )

    def test_multiple_keys(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary DESC, name"),
            ["Carol", "Alice", "dave", "Eve", "bob"],
        )

    def test_multiple_keys_with_nulls(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY dept, salary DESC"),
            ["dave", "bob", "Eve", "Carol", "Alice"],
        )

    def test_order_by_booleans(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY price > 10"),
            ["doohickey", "widget", "gadget"],
        )

    def test_limit(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary LIMIT 2"),
            ["bob", "Eve"],
        )

    def test_limit_offset(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary LIMIT 2 OFFSET 1"),
            ["Eve", "dave"],
        )

    def test_limit_without_order_by(self):
        self.assertEqual(
            self.names("SELECT name FROM people LIMIT 2"), ["Alice", "bob"]
        )

    def test_limit_zero(self):
        self.assertEqual(self.rows("SELECT name FROM people LIMIT 0"), [])

    def test_limit_larger_than_rows(self):
        self.assertEqual(len(self.rows("SELECT name FROM people LIMIT 100")), 5)

    def test_offset_past_end(self):
        self.assertEqual(self.rows("SELECT name FROM people LIMIT 5 OFFSET 10"), [])

    def test_limit_offset_zero(self):
        self.assertEqual(
            self.names("SELECT name FROM people LIMIT 1 OFFSET 0"), ["Alice"]
        )


# --------------------------------------------------------------------------
# Command-line interface
# --------------------------------------------------------------------------


class TestCLI(Base):
    def cli(self, *args, cwd=None):
        env = dict(os.environ)
        env["PYTHONPATH"] = PROJECT_ROOT + (
            os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else ""
        )
        return subprocess.run(
            [sys.executable, "-m", "minisql"] + list(args),
            cwd=cwd or PROJECT_ROOT,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=60,
        )

    def test_header_and_rows(self):
        p = self.cli(
            "SELECT name, price FROM products WHERE price > 10 ORDER BY price DESC",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name,price\r\nwidget,25\r\ngadget,12.5\r\n")

    def test_header_only_when_no_rows(self):
        p = self.cli("SELECT name FROM products WHERE FALSE", "--dir", self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name\r\n")

    def test_null_is_empty_field(self):
        p = self.cli(
            "SELECT name, bonus, id FROM people WHERE name = 'bob'",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name,bonus,id\r\nbob,,2\r\n")

    def test_booleans(self):
        p = self.cli(
            "SELECT name, bonus IS NULL AS nb FROM people WHERE id <= 2",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name,nb\r\nAlice,false\r\nbob,true\r\n")

    def test_float_formatting(self):
        p = self.cli("SELECT AVG(salary) FROM people", "--dir", self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"AVG(salary)\r\n94.0\r\n")

    def test_csv_quoting(self):
        p = self.cli("SELECT 'a,b' AS x, 'say \"hi\"' AS y FROM one", "--dir", self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b'x,y\r\n"a,b","say ""hi"""\r\n')

    def test_readme_example(self):
        p = self.cli(
            "SELECT category, COUNT(*) FROM products GROUP BY category",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"category,COUNT(*)\r\ntools,2\r\ntoys,1\r\n")

    def test_dir_defaults_to_cwd(self):
        p = self.cli("SELECT name FROM products LIMIT 1", cwd=self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name\r\nwidget\r\n")

    def test_error_exit_status_and_stderr(self):
        sql = "SELECT * FROM nosuch"
        with self.assertRaises(QueryError) as cm:
            minisql.run(sql, self.dir)
        p = self.cli(sql, "--dir", self.dir)
        self.assertEqual(p.returncode, 1)
        message = str(cm.exception)
        self.assertTrue(message)
        self.assertIn(message, p.stderr.decode())

    def test_syntax_error_exit_status(self):
        p = self.cli("SELECT FROM", "--dir", self.dir)
        self.assertEqual(p.returncode, 1)
        self.assertTrue(p.stderr.strip())

    def test_runtime_error_exit_status(self):
        p = self.cli("SELECT 'a' + 1 FROM one", "--dir", self.dir)
        self.assertEqual(p.returncode, 1)
        self.assertTrue(p.stderr.strip())


if __name__ == "__main__":
    unittest.main()

