                "SELECT dept FROM people WHERE dept IS NOT NULL "
                "GROUP BY dept ORDER BY SUM(salary)"
            ),
            [("eng",), ("sales",)],
        )

    def test_order_by_group_column(self):
        self.assertRowsExact(
            self.rows(
                "SELECT dept, COUNT(*) FROM people WHERE dept IS NOT NULL "
                "GROUP BY dept ORDER BY dept"
            ),
            [("eng", 2), ("sales", 2)],
        )


# --------------------------------------------------------------------------
# Output columns
# --------------------------------------------------------------------------


class TestColumns(Base):
    def test_star_file_order(self):
        r = self.run_sql("SELECT * FROM products")
        self.assertEqual(r.columns, ["id", "name", "category", "price"])
        self.assertRowsExact(
            r.rows,
            [
                (1, "widget", "tools", 25),
                (2, "gadget", "toys", 12.5),
                (3, "doohickey", "tools", 7),
            ],
        )

    def test_column_order_as_written(self):
        r = self.run_sql("SELECT price, name FROM products LIMIT 1")
        self.assertEqual(r.columns, ["price", "name"])
        self.assertRowsExact(r.rows, [(25, "widget")])

    def test_same_column_twice(self):
        self.assertRowsExact(
            self.rows("SELECT name, name FROM products LIMIT 1"),
            [("widget", "widget")],
        )

    def test_alias_with_as(self):
        self.assertEqual(
            self.columns("SELECT name AS product FROM products"), ["product"]
        )

    def test_alias_without_as(self):
        self.assertEqual(
            self.columns("SELECT price * 2 doubled FROM products"), ["doubled"]
        )

    def test_quoted_alias(self):
        self.assertEqual(
            self.columns('SELECT name AS "Product Name" FROM products'),
            ["Product Name"],
        )

    def test_alias_on_aggregate(self):
        r = self.run_sql("SELECT COUNT(*) AS n FROM products")
        self.assertEqual(r.columns, ["n"])
        self.assertRowsExact(r.rows, [(3,)])

    def test_plain_column_uses_header_spelling(self):
        self.assertEqual(
            self.columns("SELECT NAME, Price FROM products"), ["name", "price"]
        )

    def test_plain_column_header_spelling_mixed_case(self):
        self.assertEqual(self.columns("SELECT mixedcase FROM weird"), ["MixedCase"])

    def test_quoted_plain_column_uses_header_spelling(self):
        self.assertEqual(self.columns('SELECT "NAME" FROM products'), ["name"])

    def test_expression_text_count_star(self):
        self.assertEqual(self.columns("SELECT COUNT(*) FROM products"), ["COUNT(*)"])

    def test_expression_text_keeps_case(self):
        self.assertEqual(self.columns("SELECT count(*) FROM products"), ["count(*)"])

    def test_expression_text_with_spaces(self):
        self.assertEqual(
            self.columns("SELECT name, price * 2 FROM products"),
            ["name", "price * 2"],
        )

    def test_expression_text_without_spaces(self):
        self.assertEqual(self.columns("SELECT price*2 FROM products"), ["price*2"])

    def test_expression_text_column_case_as_written(self):
        self.assertEqual(self.columns("SELECT PRICE + 1 FROM products"), ["PRICE + 1"])

    def test_expression_text_function(self):
        self.assertEqual(
            self.columns("SELECT LOWER(name), SUM(price) FROM products GROUP BY name"),
            ["LOWER(name)", "SUM(price)"],
        )

    def test_expression_text_string_literal(self):
        self.assertEqual(
            self.columns("SELECT name || '!' FROM products"), ["name || '!'"]
        )

    def test_distinct(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT category FROM products"),
            [("tools",), ("toys",)],
        )

    def test_distinct_keeps_first(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT salary FROM people"),
            [(100,), (80,), (120,), (90,)],
        )

    def test_distinct_multiple_columns(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT dept, salary FROM people WHERE dept IS NOT NULL"),
            [("sales", 100), ("eng", 80), ("sales", 120)],
        )

    def test_distinct_case_sensitive(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT LOWER(name) = name FROM people"),
            [(False,), (True,)],
        )

    def test_distinct_with_order_by(self):
        self.assertRowsExact(
            self.rows("SELECT DISTINCT salary FROM people ORDER BY salary"),
            [(80,), (90,), (100,), (120,)],
        )


# --------------------------------------------------------------------------
# Order and limits
# --------------------------------------------------------------------------


class TestOrderAndLimits(Base):
    def names(self, sql):
        return [row[0] for row in self.rows(sql)]

    def test_file_order_without_order_by(self):
        self.assertEqual(
            self.names("SELECT name FROM people"),
            ["Alice", "bob", "Carol", "dave", "Eve"],
        )

    def test_order_by_column_not_in_output(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY price"),
            ["doohickey", "gadget", "widget"],
        )

    def test_order_by_strings_code_point(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY name"),
            ["Alice", "Carol", "Eve", "bob", "dave"],
        )

    def test_order_by_asc_explicit(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY price ASC"),
            ["doohickey", "gadget", "widget"],
        )

    def test_order_by_desc(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY price DESC"),
            ["widget", "gadget", "doohickey"],
        )

    def test_order_by_alias(self):
        self.assertEqual(
            self.names("SELECT name AS n FROM products ORDER BY n"),
            ["doohickey", "gadget", "widget"],
        )

    def test_order_by_output_name_shadows_input_column(self):
        # Output column "id" is price * 2 (50, 25.0, 14); input id is 1, 2, 3.
        self.assertRowsExact(
            self.rows("SELECT price * 2 AS id FROM products ORDER BY id"),
            [(14,), (25.0,), (50,)],
        )

    def test_order_by_position(self):
        self.assertRowsExact(
            self.rows("SELECT name, price FROM products ORDER BY 2"),
            [("doohickey", 7), ("gadget", 12.5), ("widget", 25)],
        )

    def test_order_by_position_desc(self):
        self.assertEqual(
            self.names("SELECT name, price FROM products ORDER BY 1 DESC"),
            ["widget", "gadget", "doohickey"],
        )

    def test_order_by_expression(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY price * -1"),
            ["widget", "gadget", "doohickey"],
        )

    def test_order_by_expression_on_input_row(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY LENGTH(name), id DESC"),
            ["gadget", "widget", "doohickey"],
        )

    def test_nulls_first_ascending(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY bonus"),
            ["bob", "dave", "Eve", "Carol", "Alice"],
        )

    def test_nulls_last_descending(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY bonus DESC"),
            ["Alice", "Carol", "Eve", "bob", "dave"],
        )

    def test_stable_ascending(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary"),
            ["bob", "Eve", "dave", "Alice", "Carol"],
        )

    def test_stable_descending(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary DESC"),
            ["Carol", "Alice", "dave", "bob", "Eve"],
        )

    def test_stable_constant_key(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY 1 = 1 DESC"),
            ["Alice", "bob", "Carol", "dave", "Eve"],
        )

    def test_multiple_keys(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary DESC, name"),
            ["Carol", "Alice", "dave", "Eve", "bob"],
        )

    def test_multiple_keys_with_nulls(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY dept, salary DESC"),
            ["dave", "bob", "Eve", "Carol", "Alice"],
        )

    def test_order_by_booleans(self):
        self.assertEqual(
            self.names("SELECT name FROM products ORDER BY price > 10"),
            ["doohickey", "widget", "gadget"],
        )

    def test_limit(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary LIMIT 2"),
            ["bob", "Eve"],
        )

    def test_limit_offset(self):
        self.assertEqual(
            self.names("SELECT name FROM people ORDER BY salary LIMIT 2 OFFSET 1"),
            ["Eve", "dave"],
        )

    def test_limit_without_order_by(self):
        self.assertEqual(
            self.names("SELECT name FROM people LIMIT 2"), ["Alice", "bob"]
        )

    def test_limit_zero(self):
        self.assertEqual(self.rows("SELECT name FROM people LIMIT 0"), [])

    def test_limit_larger_than_rows(self):
        self.assertEqual(len(self.rows("SELECT name FROM people LIMIT 100")), 5)

    def test_offset_past_end(self):
        self.assertEqual(self.rows("SELECT name FROM people LIMIT 5 OFFSET 10"), [])

    def test_limit_offset_zero(self):
        self.assertEqual(
            self.names("SELECT name FROM people LIMIT 1 OFFSET 0"), ["Alice"]
        )


# --------------------------------------------------------------------------
# Command-line interface
# --------------------------------------------------------------------------


class TestCLI(Base):
    def cli(self, *args, cwd=None):
        env = dict(os.environ)
        env["PYTHONPATH"] = PROJECT_ROOT + (
            os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else ""
        )
        return subprocess.run(
            [sys.executable, "-m", "minisql"] + list(args),
            cwd=cwd or PROJECT_ROOT,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=60,
        )

    def test_header_and_rows(self):
        p = self.cli(
            "SELECT name, price FROM products WHERE price > 10 ORDER BY price DESC",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name,price\r\nwidget,25\r\ngadget,12.5\r\n")

    def test_header_only_when_no_rows(self):
        p = self.cli("SELECT name FROM products WHERE FALSE", "--dir", self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name\r\n")

    def test_null_is_empty_field(self):
        p = self.cli(
            "SELECT name, bonus, id FROM people WHERE name = 'bob'",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name,bonus,id\r\nbob,,2\r\n")

    def test_booleans(self):
        p = self.cli(
            "SELECT name, bonus IS NULL AS nb FROM people WHERE id <= 2",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name,nb\r\nAlice,false\r\nbob,true\r\n")

    def test_float_formatting(self):
        p = self.cli("SELECT AVG(salary) FROM people", "--dir", self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"AVG(salary)\r\n94.0\r\n")

    def test_csv_quoting(self):
        p = self.cli("SELECT 'a,b' AS x, 'say \"hi\"' AS y FROM one", "--dir", self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b'x,y\r\n"a,b","say ""hi"""\r\n')

    def test_readme_example(self):
        p = self.cli(
            "SELECT category, COUNT(*) FROM products GROUP BY category",
            "--dir",
            self.dir,
        )
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"category,COUNT(*)\r\ntools,2\r\ntoys,1\r\n")

    def test_dir_defaults_to_cwd(self):
        p = self.cli("SELECT name FROM products LIMIT 1", cwd=self.dir)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertEqual(p.stdout, b"name\r\nwidget\r\n")

    def test_error_exit_status_and_stderr(self):
        sql = "SELECT * FROM nosuch"
        with self.assertRaises(QueryError) as cm:
            minisql.run(sql, self.dir)
        p = self.cli(sql, "--dir", self.dir)
        self.assertEqual(p.returncode, 1)
        message = str(cm.exception)
        self.assertTrue(message)
        self.assertIn(message, p.stderr.decode())

    def test_syntax_error_exit_status(self):
        p = self.cli("SELECT FROM", "--dir", self.dir)
        self.assertEqual(p.returncode, 1)
        self.assertTrue(p.stderr.strip())

    def test_runtime_error_exit_status(self):
        p = self.cli("SELECT 'a' + 1 FROM one", "--dir", self.dir)
        self.assertEqual(p.returncode, 1)
        self.assertTrue(p.stderr.strip())


if __name__ == "__main__":
    unittest.main()

