"""Black-box tests for minisql, written against SPEC.md.

Only the public API (``minisql.run``, ``minisql.QueryError``) and the CLI
(``python -m minisql``) are used.
"""

import os
import shutil
import subprocess
import sys
import tempfile
import unittest

import minisql
from minisql import QueryError

PROJECT_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

FIXTURES = {
    "products.csv": (
        "id,name,category,price\n"
        "1,widget,tools,25\n"
        "2,gadget,toys,12.5\n"
        "3,doohickey,tools,7\n"
    ),
    "people.csv": (
        "id,name,dept,salary,bonus\n"
        "1,Alice,sales,100,10\n"
        "2,bob,eng,80,\n"
        "3,Carol,sales,120,5\n"
        "4,dave,,90,\n"
        "5,Eve,eng,80,2.5\n"
    ),
    "types.csv": (
        "label,v\n"
        "int,42\n"
        "neg,-3\n"
        "zeros,007\n"
        "dec,2.5\n"
        "lead,.5\n"
        "trail,5.\n"
        "negdec,-0.5\n"
        "neglead,-.5\n"
        "empty,\n"
        "exp,1e5\n"
        "plus,+3\n"
        'space," 4"\n'
        'tspace,"4 "\n'
        "dot,.\n"
        "dash,-\n"
        "twodots,1.2.3\n"
        "word,hello\n"
        "true,TRUE\n"
        "null,NULL\n"
        'blank," "\n'
    ),
    "one.csv": "x\n1\n",
    "empty.csv": "a,b\n",
    "weird.csv": (
        'unit price,"say ""hi""",MixedCase,_x1\n'
        "3,hello,mc,9\n"
    ),
    "kw.csv": "from,order\n1,2\n",
    "my table.csv": "a\n1\n",
}


def make_fixture_dir():
    d = tempfile.mkdtemp(prefix="minisql-test-")
    for name, text in FIXTURES.items():
        with open(os.path.join(d, name), "w", newline="") as f:
            f.write(text)
    return d


class Base(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.dir = make_fixture_dir()

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.dir, ignore_errors=True)

    def run_sql(self, sql):
        return minisql.run(sql, self.dir)

    def rows(self, sql):
        return self.run_sql(sql).rows

    def columns(self, sql):
        return self.run_sql(sql).columns

    def val(self, expr):
        """Evaluate a single expression against the one-row table."""
        rows = self.rows("SELECT %s FROM one" % expr)
        self.assertEqual(len(rows), 1)
        self.assertEqual(len(rows[0]), 1)
        return rows[0][0]

    def assertExact(self, actual, expected):
        """Equal, and with exactly the same types (so 2 != 2.0, 1 != True)."""
        self.assertEqual(actual, expected)
        self.assertIs(type(actual), type(expected), (actual, expected))

    def assertRowsExact(self, actual, expected):
        actual = list(actual)
        self.assertEqual(actual, expected)
        for arow, erow in zip(actual, expected):
            self.assertIsInstance(arow, tuple)
            for a, e in zip(arow, erow):
                self.assertIs(type(a), type(e), (arow, erow))

    def assertVal(self, expr, expected):
        self.assertExact(self.val(expr), expected)

    def assertError(self, sql):
        with self.assertRaises(QueryError):
            minisql.run(sql, self.dir)


# --------------------------------------------------------------------------
# Examples from README.md and SPEC.md
# --------------------------------------------------------------------------


class TestExamples(Base):
    def test_spec_example(self):
        r = self.run_sql(
            "SELECT name, price FROM products WHERE price > 10 ORDER BY price DESC"
        )
        self.assertEqual(r.columns, ["name", "price"])
        self.assertRowsExact(r.rows, [("widget", 25), ("gadget", 12.5)])

    def test_result_shape(self):
        r = self.run_sql("SELECT name FROM products")
        self.assertIsInstance(r.columns, list)
        self.assertIsInstance(r.rows, list)
        for row in r.rows:
            self.assertIsInstance(row, tuple)

    def test_readme_example(self):
        r = self.run_sql(
            "SELECT category, COUNT(*) FROM products GROUP BY category"
        )
        self.assertEqual(r.columns, ["category", "COUNT(*)"])
        self.assertRowsExact(r.rows, [("tools", 2), ("toys", 1)])


# --------------------------------------------------------------------------
# Tables
# --------------------------------------------------------------------------


class TestTables(Base):
    def v(self, label):
        rows = self.rows("SELECT v FROM types WHERE label = '%s'" % label)
        self.assertEqual(len(rows), 1)
        return rows[0][0]

    def test_integer(self):
        self.assertExact(self.v("int"), 42)

    def test_negative_integer(self):
        self.assertExact(self.v("neg"), -3)

    def test_integer_leading_zeros(self):
        self.assertExact(self.v("zeros"), 7)

    def test_decimal(self):
        self.assertExact(self.v("dec"), 2.5)

    def test_decimal_leading_dot(self):
        self.assertExact(self.v("lead"), 0.5)

    def test_decimal_trailing_dot(self):
        self.assertExact(self.v("trail"), 5.0)

    def test_negative_decimal(self):
        self.assertExact(self.v("negdec"), -0.5)

    def test_negative_decimal_leading_dot(self):
        self.assertExact(self.v("neglead"), -0.5)

    def test_empty_is_null(self):
        self.assertIsNone(self.v("empty"))

    def test_exponent_is_string(self):
        self.assertExact(self.v("exp"), "1e5")

    def test_plus_sign_is_string(self):
        self.assertExact(self.v("plus"), "+3")

    def test_leading_space_is_string(self):
        self.assertExact(self.v("space"), " 4")

    def test_trailing_space_is_string(self):
        self.assertExact(self.v("tspace"), "4 ")

    def test_lone_dot_is_string(self):
        self.assertExact(self.v("dot"), ".")

    def test_lone_dash_is_string(self):
        self.assertExact(self.v("dash"), "-")

    def test_two_dots_is_string(self):
        self.assertExact(self.v("twodots"), "1.2.3")

    def test_word_is_string(self):
        self.assertExact(self.v("word"), "hello")

    def test_true_text_is_string(self):
        self.assertExact(self.v("true"), "TRUE")

    def test_null_text_is_string(self):
        self.assertExact(self.v("null"), "NULL")

    def test_whitespace_only_is_string(self):
        self.assertExact(self.v("blank"), " ")

    def test_header_gives_column_names(self):
        self.assertEqual(
            self.columns("SELECT * FROM people"),
            ["id", "name", "dept", "salary", "bonus"],
        )

    def test_header_only_file(self):
        r = self.run_sql("SELECT * FROM empty")
        self.assertEqual(r.columns, ["a", "b"])
        self.assertEqual(r.rows, [])

    def test_missing_table(self):
        self.assertError("SELECT * FROM nosuch")

    def test_quoted_table_name(self):
        self.assertRowsExact(self.rows('SELECT a FROM "my table"'), [(1,)])

    def test_unknown_column(self):
        self.assertError("SELECT nosuch FROM products")

    def test_unknown_column_in_where(self):
        self.assertError("SELECT name FROM products WHERE nosuch = 1")

    def test_unknown_column_in_order_by(self):
        self.assertError("SELECT name FROM products ORDER BY nosuch")

    def test_unknown_column_in_group_by(self):
        self.assertError("SELECT COUNT(*) FROM products GROUP BY nosuch")


# --------------------------------------------------------------------------
# Syntax: keywords, names, literals
# --------------------------------------------------------------------------


class TestNamesAndKeywords(Base):
    def test_keywords_case_insensitive(self):
        r = self.run_sql(
            "select name, price from products where price > 10 order by price desc"
        )
        self.assertRowsExact(r.rows, [("widget", 25), ("gadget", 12.5)])

    def test_keywords_mixed_case(self):
        self.assertRowsExact(
            self.rows("SeLeCt DiStInCt category FrOm products LiMiT 1 oFfSeT 1"),
            [("toys",)],
        )

    def test_literal_keywords_case_insensitive(self):
        self.assertIs(self.val("true"), True)
        self.assertIs(self.val("False"), False)
        self.assertIsNone(self.val("null"))

    def test_function_names_case_insensitive(self):
        self.assertVal("lower('AB')", "ab")
        self.assertVal("Upper('ab')", "AB")
        self.assertRowsExact(self.rows("SELECT count(*) FROM products"), [(3,)])

    def test_column_names_case_insensitive(self):
        self.assertRowsExact(
            self.rows("SELECT NAME FROM products WHERE PrIcE > 20"),
            [("widget",)],
        )

    def test_underscore_and_digits_in_name(self):
        self.assertRowsExact(self.rows("SELECT _x1 FROM weird"), [(9,)])

    def test_quoted_name_with_space(self):
        r = self.run_sql('SELECT "unit price" FROM weird')
        self.assertEqual(r.columns, ["unit price"])
        self.assertRowsExact(r.rows, [(3,)])

    def test_quoted_name_with_escaped_quote(self):
        r = self.run_sql('SELECT "say ""hi""" FROM weird')
        self.assertEqual(r.columns, ['say "hi"'])
        self.assertRowsExact(r.rows, [("hello",)])

    def test_quoted_name_case_insensitive(self):
        r = self.run_sql('SELECT "MIXEDCASE" FROM weird')
        self.assertEqual(r.columns, ["MixedCase"])
        self.assertRowsExact(r.rows, [("mc",)])

    def test_quoted_keyword_names(self):
        r = self.run_sql('SELECT "from", "order" FROM kw')
        self.assertEqual(r.columns, ["from", "order"])
        self.assertRowsExact(r.rows, [(1, 2)])

    def test_keyword_not_usable_as_unquoted_column(self):
        self.assertError("SELECT from FROM kw")

    def test_keyword_order_not_usable_as_unquoted_column(self):
        self.assertError("SELECT order FROM kw")

    def test_keyword_not_usable_as_unquoted_alias(self):
        self.assertError("SELECT name AS limit FROM products")

    def test_keyword_not_usable_in_where(self):
        self.assertError('SELECT "from" FROM kw WHERE order = 2')


class TestLiterals(Base):
    def test_integer_literal(self):
        self.assertVal("42", 42)

    def test_decimal_literal(self):
        self.assertVal("2.5", 2.5)

    def test_decimal_literal_leading_dot(self):
        self.assertVal(".5", 0.5)

    def test_string_literal(self):
        self.assertVal("'hello world'", "hello world")

    def test_string_literal_escaped_quote(self):
        self.assertVal("'it''s'", "it's")

    def test_empty_string_literal(self):
        self.assertVal("''", "")

    def test_string_literal_preserves_case_and_keywords(self):
        self.assertVal("'SELECT From'", "SELECT From")

    def test_null_literal(self):
        self.assertIsNone(self.val("NULL"))

    def test_true_false_literals(self):
        self.assertIs(self.val("TRUE"), True)
        self.assertIs(self.val("FALSE"), False)


class TestSyntaxErrors(Base):
    def test_empty_query(self):
        self.assertError("")

    def test_garbage(self):
        self.assertError("this is not sql")

    def test_select_only(self):
        self.assertError("SELECT")

    def test_missing_columns(self):
        self.assertError("SELECT FROM products")

    def test_missing_from(self):
